    "title": "소담매니저 후기",
    "author": "터보",
    "body": "실장님 추천으로 소담매니저 봤습니다.\n참하고 단아한 외모에,, 후기에서처럼 \n박민영 싱크가 있네요.\n기대보다 훨씬 예뻐서 놀랐네요 ^^\n글래머러스한 취향인 저로서는 더욱더\n취저였고,,\n\n조곤조곤한 말투와 친절한 응대 \n기본이고 마사지도 성의껏 잘해주셔서 \n힐링 제대로 했네요.\n재접 100퍼 추천 매니저인듯 ㅎ",
