    "id": "3293",
    "title": "혜담",
    "author": "가을",
    "body": "키는 160 초중반에\n슬림한 체형이나 \n몸매가 이뿐 편임\n\n들어가자마자 반갑게 맞아주고\n목소리도 나긋나긋하고\n 대화가 잘 통하고\n응대가 전반적으로 굉장히 뛰어남\n\n컨셉은 ㅈㅎㄷ이어서\n터치도 관대하고\n재접 만족도 높음",
