    "body": "나이는 중간정도로\n밝은 표정에 \n상대방에 대한 배려가\n묻어난다.\n\n그래서 서비스도\n평범하지 않고\n야릇한 음성이 분위기를\n흥분시킴\n\n특이한 취향에\n고객만족도가 매우 높음\n\n시간되면 보시길\n적극 추천함",
