    "title": "혜담",
    "author": "테슬라",
    "body": "실장님 추천으로 혜담이 봤습니다.\n슬림한 분이 계시네요. \n서비스는 정말 열심히 하십니다.\n기대 이상의 서비스를 받고 갑니다.\n슬림 좋아하시는 분, 서비스 좋아하는 분들 추천합니다.\n요즘 매우 자주 나온다고 하네요.\n말도 끊기지않게 열심히 맞춰주네요.\n성격도 좋은거 같습니다!!!\n한번만나보세요",
