    "title": "수화",
    "author": "겨울",
    "body": "첫인상은 \n서구적으로 미인형임\n근데 대화를 해보면\n말을 많이 시켜줘서 어색함 없이 \n시간이 금방 감\n마사지도 오일로 잘해주시고 \n재미가 있음 \n글래머러스 \n가슴이 좋아 가슴 좋아하는 분\n강추임",
