    "body": "제시 봣어요\n후기글이 워낙좋아 실물 영접하니\n소문대로네요\n운동으로 다져진 비율좋은 몸매에\n비키니 차림으로 당당히 서있는 모습이\n여신입니다 ㅋ\n반가워서 힙을 살짝 만지니 탄력죽이네요\n남미 아가씨 보는줄ㅋ\nㅅㄱ도 예뻐서 재방문율이 제일 높을것같아요\n떠오르는 에이스 제시 강추합니다!",
