    "body": "윤정씨 봤어요\n\n20중반이고 슬림하시고 화려한 미인상\n\n우선 착하시고 상대말에 경청해주심\n\n마사지도 말했더니 굉장히 신경써서 해주셨음\n\nㅅㄱ는 비플정도..\n\n솝트지만 매너만 갖춘다면 터치에 박하지 않으시니\n\n시간될때 접해보세요들",
